import {createOwnerOrders} from './owner-orders.mjs';
import {deliveryRules,storeDefaults} from './store-settings.mjs';
import {defaults} from './core.mjs';
import {checkoutPaymentOptions,paymentSelector} from './payment-options.mjs';
import {openRazorpayTest} from './razorpay-checkout.mjs';
import {commerceConfig} from './commerce-config.mjs';
import {stages,stageLabels,previewShipping,validateAddress,quoteCheckout,previewTracking,createManualPreviewOrder,submitManualPreview} from './commerce-model.mjs';
// Standard UPI deep link; amount is in rupees with paise precision.
const upiLink=(p,o)=>'upi://pay?'+new URLSearchParams({pa:p.upiId,pn:p.payeeName,am:(o.totalPaise/100).toFixed(2),cu:'INR',tn:'Drip & Dusk '+o.ref});
const rupees=p=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',minimumFractionDigits:0,maximumFractionDigits:2}).format(p/100),when=s=>new Date(s).toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short'});
export function createCheckout({getAccount=()=>null,openModal,hideModalForPayment=()=>{},getState,getBasket,commit,saveBag,esc,imageURL,icon,toast,copy}){
 let draft=null,session=null,latest=null,busy=false,info={mode:'loading',provider:'none',ready:false},isAPI=commerceConfig.mode==='api';
 const live=()=>info.mode==='live';
 const ownerOrders=createOwnerOrders({api,isAPI,getState,commit,esc,toast,icon});
 const base=commerceConfig.apiBase.replace(/\/$/,'');
 async function api(path,{method='GET',body,token}={}){const r=await fetch(base+path,{method,signal:AbortSignal.timeout(15000),credentials:'same-origin',headers:{...(body?{'Content-Type':'application/json'}:{}),...(token?{Authorization:'Bearer '+token}:{})},body:body?JSON.stringify(body):undefined});let data;try{data=await r.json()}catch{throw Error('Checkout service is unavailable. Please try again later.')}if(!r.ok)throw Object.assign(Error(data.error||'The request could not be completed.'),{status:r.status,code:data.code});return data;}
 function selectedPayment(){return checkoutPaymentOptions(info).find(p=>p.id===draft?.paymentMethod)||checkoutPaymentOptions(info).find(p=>p.available);}
 // Only non-live (staging) checkouts carry a banner; live checkout shows none.
 function notice(){return live()||info.mode==='loading'?'':`<div class="checkout-mode"><b>Test checkout</b><span>No real money is collected on this test checkout.</span></div>`}
 function steps(active){return `<ol class="checkout-progress" aria-label="Checkout progress">${['Delivery','Review & pay','Confirmation'].map((s,i)=>`<li class="${i===active?'current':i<active?'complete':''}" ${i===active?'aria-current="step"':''}><span>${i+1}</span>${s}</li>`).join('')}</ol>`}
 function summary(q){return `<aside class="checkout-summary"><p class="eyebrow">YOUR SELECTION</p>${q.lines.map(l=>`<div class="checkout-line"><img src="${imageURL(l.image)}" alt="${esc(l.name)}" width="54" height="65"><div><b>${esc(l.name)}</b><span>${l.size} ml · ${esc(l.format)} · Qty ${l.qty}</span></div><strong>${rupees(l.unitPaise*l.qty)}</strong></div>`).join('')}<dl class="checkout-totals"><div><dt>Subtotal</dt><dd>${rupees(q.subtotalPaise)}</dd></div><div><dt>Delivery</dt><dd>${q.feePaise===null?'Calculated next':q.feePaise===0?'Included':rupees(q.feePaise)}</dd></div><div class="checkout-total"><dt>${q.feePaise===null?'Subtotal':'Total'}</dt><dd>${rupees(q.totalPaise)}</dd></div></dl><p class="fineprint">${q.deliveryLabel||'Delivery charges appear before payment.'}</p></aside>`}
 async function initialize(){if(!isAPI)return null;try{const [configuration,data]=await Promise.all([api('/api/config'),api('/api/catalogue')]);info=configuration;commit({...getState(),settings:{...defaults().settings,...storeDefaults,...data.settings}});return data.products}catch(e){info={mode:'unavailable',provider:'none',ready:false};toast('The catalogue could not be refreshed. Checkout is paused; please try again shortly.');return null}}
 function open(){
  if(!getBasket().length)return toast('Add a bottle or decant to your bag first.');
  if(info.ready===false)return openModal('Checkout is unavailable.',`<p>Checkout is not available right now. Please try again shortly, or contact us and we’ll help you place your order.</p><button class="btn outline" data-action="contact">Ask Drip & Dusk</button>`,'checkout');
  if(session?.status==='pending'){showPaymentStatus();return;}
  if(draft?.address&&!session&&!latest){address();return;}
  draft={address:{name:'',phone:'',line1:'',line2:'',city:'',state:'',postcode:''},consent:false,paymentMethod:checkoutPaymentOptions(info).find(p=>p.available)?.id||'manual_upi',requestId:crypto.randomUUID(),quote:null};session=null;latest=null;address();
 }
 function address(error=''){
  let q;try{q=quoteCheckout(getState().products,getBasket(),'411001',previewShipping);q={...q,feePaise:null,totalPaise:q.subtotalPaise,deliveryLabel:''}}catch(e){return openModal('Review your bag.',`<p>${esc(e.message)}</p><button class="btn" data-action="basket">Back to bag</button>`,'checkout')}
  const a=draft.address;
  openModal('Make it yours.',`${notice()}${steps(0)}<div class="checkout-layout"><form id="delivery-form" class="checkout-form"><p class="eyebrow">THE DETAILS THAT GET IT TO YOU</p><h3>Where shall it go?</h3><p class="checkout-account-note">${getAccount()?.user?'Signed in as '+esc(getAccount().user.email):'Checking out as a guest. <a href="#account/checkout">Sign in — optional <svg class=ui-icon aria-hidden=true focusable=false><use href=#arrow-up-right-icon></use></svg></a>'}</p><div class="form-grid">${[['Full name','name','text',80],['Mobile number','phone','tel',16],['Street address','line1','text',160],['Apartment / landmark — optional','line2','text',160],['City','city','text',80],['State','state','text',80],['PIN code','postcode','text',6]].map(([label,key,type,max])=>`<label class="${['name','line1','line2'].includes(key)?'span-2':''}">${label}<input name="${key}" type="${type}" value="${esc(a[key])}" maxlength="${max}" ${key==='line2'?'':'required'} ${key==='postcode'?'inputmode="numeric" pattern="[1-9][0-9]{5}"':''} autocomplete="${{name:'name',phone:'tel',line1:'address-line1',line2:'address-line2',city:'address-level2',state:'address-level1',postcode:'postal-code'}[key]}"></label>`).join('')}<label>Country<input value="India" readonly aria-label="Country"></label></div><label class="checkout-consent"><input name="consent" type="checkbox" ${draft.consent?'checked':''}><span>Send my order confirmation and tracking link on WhatsApp.</span></label><p id="checkout-error" class="form-error" role="alert">${esc(error)}</p><button class="btn full" type="submit">Review delivery & total <svg class=ui-icon aria-hidden=true focusable=false><use href=#arrow-up-right-icon></use></svg></button><p class="fineprint">${live()?'Your details are used only to deliver this order. WhatsApp updates are optional.':'Test checkout: these details are replaced with a sample address before saving.'}</p></form>${summary(q)}</div>`,'checkout','DRIP & DUSK / CHECKOUT');
  document.querySelector('#delivery-form').addEventListener('input',e=>{if(['name','phone','line1','line2','city','state','postcode'].includes(e.target.name))draft.address[e.target.name]=e.target.value;if(e.target.name==='consent')draft.consent=e.target.checked});
  document.querySelector('#delivery-form').addEventListener('submit',async e=>{e.preventDefault();if(busy)return;const f=new FormData(e.currentTarget);draft.address=Object.fromEntries(['name','phone','line1','line2','city','state','postcode'].map(k=>[k,String(f.get(k)||'')]));draft.consent=f.has('consent');busy=true;const button=e.currentTarget.querySelector('button[type=submit]');button.disabled=true;try{draft.address=validateAddress(draft.address);draft.quote=isAPI?await api('/api/checkout/quote',{method:'POST',body:{basket:getBasket(),postcode:draft.address.postcode}}):quoteCheckout(getState().products,getBasket(),draft.address.postcode,deliveryRules(getState().settings));busy=false;review()}catch(e){document.querySelector('#checkout-error').textContent=e.message;button.disabled=false}finally{busy=false}});
 }
 function review(error=''){
  const a=draft.address,method=selectedPayment();
  openModal('One final look.',`${notice()}${steps(1)}<div class="checkout-layout"><section class="checkout-review"><p class="eyebrow">YOUR DELIVERY DETAILS</p><h3>${esc(a.name)}</h3><p>${esc(a.line1)}${a.line2?'<br>'+esc(a.line2):''}<br>${esc(a.city)}, ${esc(a.state)} ${esc(a.postcode)}<br>India · +${esc(a.phone)}</p><button class="text-link" data-action="checkout-address">Edit delivery details <svg class=ui-icon aria-hidden=true focusable=false><use href=#arrow-up-right-icon></use></svg></button><div class="checkout-payment">${paymentSelector(info,draft.paymentMethod,!!session,esc)}<h4>${method?.id==='manual_upi'?'A direct payment. A personal confirmation.':'Pay securely with Razorpay'}</h4><p>${method?.id==='manual_upi'?'Place your order, pay the exact total to our UPI ID, then enter the UPI transaction reference (UTR). Your order is confirmed once we verify the payment.':live()?'Pay by card, UPI, netbanking or wallet in Razorpay’s secure window. Your order is confirmed as soon as the payment is verified.':'Open Razorpay in test mode. Your order is confirmed only after the backend verifies a captured payment for the correct amount.'}</p><p id="checkout-error" class="form-error" role="alert">${esc(error)}</p><button class="btn full" data-action="checkout-pay" ${busy||!method?.available?'disabled':''}>${method?.id==='manual_upi'?'Place order · Pay by UPI':'Pay '+rupees(draft.quote.totalPaise)+' with Razorpay'} ${icon('bag')}</button><p class="fineprint">${draft.consent?'WhatsApp updates requested.':'WhatsApp updates are switched off.'}</p><p class="fineprint checkout-terms">By placing this order you agree to our <a href="/terms" target="_blank" rel="noopener">Terms</a> and <a href="/refunds" target="_blank" rel="noopener">Refund & cancellation policy</a>.</p></div></section>${summary(draft.quote)}</div>${session?`<p class="fineprint">Payment already started? <a class="text-link" href="#track/${esc(session.id)}/${esc(session.token)}">Open your private payment status <svg class=ui-icon aria-hidden=true focusable=false><use href=#arrow-up-right-icon></use></svg></a></p>`:''}`,'checkout','DRIP & DUSK / CHECKOUT');
 }
 async function pay(){
  if(busy||!draft?.quote)return;busy=true;document.querySelector('[data-action=checkout-pay]')?.setAttribute('disabled','');
  try{
   const method=selectedPayment();if(!method?.available)throw Error('This payment method is not available right now.');
   if(!isAPI){const result=createManualPreviewOrder(getState(),getBasket(),draft.quote,{requestId:draft.requestId,consent:draft.consent});if(!commit(result.state))throw Error('Could not save the order. Your bag has not been cleared.');saveBag([]);draft.address=null;latest=result.order;location.hash='track/'+latest.id+'/'+latest.token;return;}
   session??=await api('/api/orders',{method:'POST',body:{quoteId:draft.quote.quoteId,basket:getBasket(),address:draft.address,whatsappConsent:draft.consent,requestId:draft.requestId,paymentMethod:draft.paymentMethod}});
   if(session.provider==='manual_upi'){saveBag([]);draft.address=null;location.hash='track/'+session.id+'/'+session.token;return;}
   if(session.status&&session.status!=='pending'){await paid();return;}
   if(session.provider==='preview'){await api('/api/orders/'+session.id+'/preview-payment',{method:'POST',body:{outcome:'success'},token:session.token});await paid();return;}
   await gatewayPayment();
  }catch(e){review(e.message)}finally{busy=false;document.querySelector('[data-action=checkout-pay]')?.removeAttribute('disabled')}
 }
 async function gatewayPayment(){
  const current=session,outcome=await openRazorpayTest(current,{prefill:draft?.address||{},beforeOpen:hideModalForPayment});
  if(outcome.type==='submitted'){
   try{await api('/api/orders/'+current.id+'/verify',{method:'POST',body:outcome.result,token:current.token});await paid();}
   catch(e){await showPaymentStatus();toast(e.message+' Refresh the order status before trying again.');}
  }else{await showPaymentStatus();toast(outcome.failed?'The payment attempt did not complete. Check the status before retrying.':'Payment window closed. Your order remains unconfirmed until verification.');}
 }
 async function showPaymentStatus(){const hash='#track/'+session.id+'/'+session.token;if(location.hash===hash)await track(session.id,session.token);else location.hash=hash;}
 async function paid(){const result=await api('/api/orders/'+session.id,{token:session.token});session.status=result.status;if(stages.includes(result.status)||result.paymentStatus==='captured_unallocated'){saveBag([]);if(draft)draft.address=null;const data=await api('/api/catalogue');commit({...getState(),products:data.products});}await showPaymentStatus();}
 function trackingLink(o){const u=new URL(location.href);u.hash='track/'+encodeURIComponent(o.id)+'/'+encodeURIComponent(o.token);return u.href;}
 async function track(id,token){
  try{latest=isAPI?{...await api('/api/orders/'+encodeURIComponent(id),{token}),id,token}:previewTracking(getState(),id,token);if(location.hash!=='#track/'+id+'/'+token)return;if(session?.id===id)session.status=latest.status;renderTrack(latest);if(latest.paymentMethod==='manual_upi')bindManualForm(latest)}catch(e){if(location.hash!=='#track/'+id+'/'+token)return;openModal('Tracking link unavailable.',`<p>${esc(e.message)}</p><p class="fineprint">Check that you copied the complete tracking link.</p><button class="btn outline" data-action="contact">Ask Drip & Dusk</button>`,'tracking')}
 }
 function renderTrack(o){
  const n=stages.indexOf(o.status),manual=o.paymentMethod==='manual_upi',preview=o.mode==='preview'||o.mode==='manual_demo',test=o.mode!=='live',message=`Drip & Dusk · ${o.ref}\nYour ${test?'test ':''}order is ${stageLabels[o.status]?.toLowerCase()||o.status}.\nTotal: ${rupees(o.totalPaise)}\nTrack: ${trackingLink(o)}`;
  openModal('Your fragrance journey.',`${test?'<div class="checkout-mode"><b>Test order</b><span>No real money was collected for this order.</span></div>':''}<div class="order-heading"><div><p class="eyebrow">${esc(o.ref)}</p><h3>${esc(stageLabels[o.status]||o.status)}</h3><p>${o.status==='confirmed'?'Your selection is confirmed and ready for the next step.':o.status==='pending'?(manual?'Pay the exact total to the UPI ID below, then submit your transaction reference.':'Your payment is not verified yet. Continue with the same payment below, or refresh its status.'):o.status==='awaiting_verification'?'Reference received. We’ll confirm your order as soon as we verify the payment.':o.status==='payment_review'?'Your payment needs the seller’s attention. Please contact Drip & Dusk.':'Follow your order’s progress below.'}</p></div><span class="order-total">${rupees(o.totalPaise)}</span></div>${manual?manualPayment(o):isAPI&&o.paymentMethod==='razorpay'&&o.status==='pending'?`<div class="razorpay-pending"><p>Retrying uses this existing order. No additional payment fee is added.</p><button class="btn" data-action="order-resume-razorpay" ${busy?'disabled':''}>Continue payment with Razorpay <svg class=ui-icon aria-hidden=true focusable=false><use href=#arrow-up-right-icon></use></svg></button><p class="fineprint">${o.expiresAt?'Your bottles are held until '+esc(when(o.expiresAt))+'.':''}</p></div>`:''}${o.shipment?.awb||o.shipment_id?`<section class="shipment-summary"><h4>Shipment details</h4><p>${esc(o.shipment?.courier||o.courier_name||'Courier')} · AWB ${esc(o.shipment?.awb||o.shipment_id)}</p>${o.shipment?.trackingUrl||o.tracking_url?`<a class="text-link" href="${esc(o.shipment?.trackingUrl||o.tracking_url)}" target="_blank" rel="noopener noreferrer">Track with courier <svg class=ui-icon aria-hidden=true focusable=false><use href=#arrow-up-right-icon></use></svg></a>`:''}</section>`:''}<ol class="order-timeline" aria-label="Order progress">${stages.map((stage,i)=>`<li class="${i<=n?'done':''} ${i===n?'current':''}" ${i===n?'aria-current="step"':''}><span>${i<n?'<svg class=ui-icon aria-hidden=true focusable=false><use href=#check-icon></use></svg>':i+1}</span><b>${stageLabels[stage]}</b><small>${o.events.find(e=>e.status===stage)?when(o.events.find(e=>e.status===stage).at):'Awaiting update'}</small></li>`).join('')}</ol><div class="tracking-columns"><section><h4>In your order</h4>${summary({...o,preview,deliveryLabel:o.deliveryLabel})}</section><section class="notification-card"><p class="eyebrow">WHATSAPP UPDATES</p><h4>${manual||!info.whatsappConnected?'Personal updates':o.notificationStatus==='not_requested'?'Updates switched off':preview?'Message preview':'Order notifications'}</h4><p>${manual||!info.whatsappConnected?'Once your payment is confirmed, we can share updates with you on WhatsApp. Keep this private tracking link to check your order at any time.':o.notificationStatus==='not_requested'?'You did not opt in to WhatsApp updates. Your tracking link still works.':preview?'This is the message the connected service will send after payment verification.':o.notificationStatus==='delivered'?'Your confirmation message was delivered.':o.notificationStatus==='submitted'?'Your confirmation was submitted to WhatsApp.':o.notificationStatus==='not_requested'?'You did not opt in to WhatsApp updates. Your tracking link still works.':'WhatsApp delivery is pending. Your confirmed order is saved independently of message delivery.'}</p>${preview&&!manual&&o.notificationStatus!=='not_requested'?`<pre class="order-message">${esc(message)}</pre>`:''}<p class="fineprint">Tracking updates as your order is packed, shipped and delivered.</p><div class="order-tools"><button class="text-link" data-action="order-copy" data-id="${esc(o.id)}">Copy tracking link <svg class=ui-icon aria-hidden=true focusable=false><use href=#copy-icon></use></svg></button><button class="text-link" data-action="order-refresh">Refresh status</button><button class="text-link" data-action="contact">Contact Drip & Dusk ${icon('chat')}</button></div></section></div>`,'tracking','DRIP & DUSK / ORDER TRACKING');
 }
 function admin(container,filters=null){
  if(filters)ownerOrders.setFilters(filters);
  if(isAPI){serverAdmin(container);return;}
  ownerOrders.render(container).catch(e=>toast(e.message));
 }
 function manualPayment(o){
  if(!['pending','awaiting_verification'].includes(o.status))return '';
  const p=o.payment||info.payment||{},waiting=o.status==='awaiting_verification';
  return `<section class="upi-payment-card"><div><p class="eyebrow">${waiting?'REFERENCE SUBMITTED':'PAYMENT DETAILS'}</p><h4>${waiting?'We’re verifying your payment.':'Pay directly with UPI.'}</h4><p>${waiting?'Your order is confirmed as soon as we match this reference to the payment received.':p.sample?'This is a sample merchant identity. Do not attempt a real payment.':'Pay exactly the order total from any UPI app. Add your order reference '+esc(o.ref)+' as the payment note.'}</p>${p.upiId?`<dl><div><dt>Payee</dt><dd>${esc(p.payeeName)}</dd></div><div><dt>UPI ID</dt><dd>${esc(p.upiId)}</dd></div><div><dt>Order total</dt><dd>${rupees(o.totalPaise)}</dd></div></dl>`:'<p class="form-error">UPI details are unavailable right now. Please contact us before paying.</p>'}<p class="fineprint">${!o.expiresAt?'':waiting?'Your bottles are held for you until '+esc(when(o.expiresAt))+' while we verify the payment.':'Pay before '+esc(when(o.expiresAt))+'. Unpaid orders are released after that time.'}</p></div>${p.upiId&&!p.sample?`<div class="upi-pay-mark"><svg aria-hidden="true"><use href="#bottle-icon"/></svg><b>${rupees(o.totalPaise)}</b>${!waiting?`<a class="btn" href="${esc(upiLink(p,o))}">Open UPI app</a><span>On a phone, this opens your UPI app with the amount filled in.</span>`:''}</div>`:''}${!waiting?`<form id="upi-reference-form" class="span-2"><label>UPI transaction reference (UTR)<input name="reference" placeholder="12-digit UTR from your payment app" pattern="[A-Za-z0-9-]{6,40}" minlength="6" maxlength="40" autocomplete="off" required></label><p id="upi-error" class="form-error" role="alert"></p><button class="btn" type="submit">Submit payment reference <svg class=ui-icon aria-hidden=true focusable=false><use href=#arrow-up-right-icon></use></svg></button><p class="fineprint">We check this against the payment received before confirming your order.</p></form>`:''}</section>`;
 }
 function bindManualForm(o){document.querySelector('#upi-reference-form')?.addEventListener('submit',async e=>{e.preventDefault();const button=e.currentTarget.querySelector('button');button.disabled=true;try{const reference=String(new FormData(e.currentTarget).get('reference')).trim();if(isAPI)await api('/api/orders/'+o.id+'/payment-submission',{method:'POST',token:o.token,body:{reference}});else if(!commit(submitManualPreview(getState(),o.id,reference)))throw Error('Could not save this reference.');await track(o.id,o.token);}catch(e){const error=document.querySelector('#upi-error');if(error)error.textContent=e.message;}finally{button.disabled=false;}});}
 async function serverAdmin(container){
  try{await ownerOrders.render(container);
  }catch(e){if(getAccount()?.ownerRequired){container.innerHTML='<div class="notice">Owner access could not be verified. Sign in with the approved owner account to continue.</div><a class="btn" href="#account/admin">Owner sign-in <svg class=ui-icon aria-hidden=true focusable=false><use href=#arrow-up-right-icon></use></svg></a>';return;}container.innerHTML=`<form id="owner-login" class="settings-form"><h3>Owner sign-in.</h3><label>Owner access key<input name="token" type="password" autocomplete="current-password" required></label><p id="owner-login-error" class="form-error" role="alert"></p><button class="btn" type="submit">Sign in</button></form>`;container.querySelector('form').addEventListener('submit',async e=>{e.preventDefault();try{await api('/api/admin/login',{method:'POST',body:{token:new FormData(e.currentTarget).get('token')}});location.reload();}catch(e){container.querySelector('#owner-login-error').textContent=e.message;}});}
 }
 async function handle(action,el){
  if(action==='checkout-method'){if(busy||session)return;const method=checkoutPaymentOptions(info).find(p=>p.id===el.dataset.method&&p.available);if(method&&draft){draft.paymentMethod=method.id;review();document.querySelector('[data-action="checkout-method"][data-method="'+method.id+'"]')?.focus({preventScroll:true});}return;}
  if(action==='order-resume-razorpay'){
   if(busy||!latest||latest.paymentMethod!=='razorpay'||latest.status!=='pending')return;busy=true;el.disabled=true;
   try{session=await api('/api/orders/'+latest.id+'/payment-session',{token:latest.token});session.token=latest.token;if(session.status!=='pending'){await paid();return;}await gatewayPayment();}
   catch(e){await track(latest.id,latest.token);toast(e.message);}
   finally{busy=false;document.querySelector('[data-action="order-resume-razorpay"]')?.removeAttribute('disabled');}return;
  }
  if(action==='checkout-open'){if(location.hash==='#checkout')open();else location.hash='checkout';}
  if(action==='checkout-address'){if(!busy&&!session){draft.requestId=crypto.randomUUID();address()}else if(session)await showPaymentStatus();}
  if(action==='checkout-pay')await pay();
  if(action==='order-refresh'&&latest)await track(latest.id,latest.token);
  if(action==='order-copy'&&latest)copy(trackingLink(latest),'Tracking link copied.');
  if(action==='order-server-cancel'){await api('/api/admin/orders/'+el.dataset.id+'/cancel',{method:'POST',body:{}});admin(document.querySelector('#admin-content'));}
  if(action==='order-signout'){await api('/api/admin/logout',{method:'POST',body:{}});admin(document.querySelector('#admin-content'));}
  if(action==='order-server-pack'){try{await api('/api/admin/orders/'+el.dataset.id+'/status',{method:'POST',body:{status:el.dataset.stage||'packed'}});admin(document.querySelector('#admin-content'))}catch(e){toast(e.message)}}
 }
 return {initialize,open,track,handle,admin,get connected(){return isAPI},get mode(){return info.mode},api};
}
